insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều5_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Các nội dung quản lý thuế bao gồm:
nộp, tiền phạt; ấn định thuế; hoàn thuế; xử lý tiền thuế, tiền chậm nộp, tiền phạt
nộp thừa; miễn thuế; giảm thuế; không chịu thuế; không thu thuế; khoanh tiền
thuế nợ; xóa tiền thuế nợ; miễn tiền chậm nộp; miễn tiền phạt; tính tiền chậm nộp,
không tính tiền chậm nộp; gia hạn nộp thuế, tiền chậm nộp, tiền phạt; gia hạn nộp
hồ sơ khai thuế; nộp dần tiền thuế nợ; cưỡng chế thi hành quyết định hành chính
về quản lý thuế;
