insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều6_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Quản lý thuế phải bảo đảm nguyên tắc công khai, minh bạch, bình đẳng,
lấy người nộp thuế làm trung tâm phục vụ, bảo đảm quyên và lợi ích hợp pháp
của người nộp thuế, nâng cao hiệu lực, hiệu quả quản lý thu ngân sách nhà nước.$md$,$md$Luật quản lý thuế 2025_Điều6$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều6_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Người nộp thuế có nghĩa vụ nộp thuế, các khoản thu khác thuộc ngân
sách nhà nước theo quy định của luật thuế và quy định của pháp luật. Người nộp
thuế tự xác định nghĩa vụ thuế, các khoản thu khác thuộc ngân sách nhà nước phải
nộp, tự kê khai thuế, các khoản thu khác thuộc ngân sách nhà nước và tự nộp thuế,
các khoản thu khác thuộc ngân sách nhà nước vào ngân sách nhà nước theo quy
định của pháp luật về thuế, pháp luật về quản lý thuế và các quy định khác của
pháp luật có liên quan, trừ trường hợp do cơ quan quản lý thuế tính thuế, khoản
thu khác, thông báo thuế, khoản thu khác theo quy định của pháp luật.$md$,$md$Luật quản lý thuế 2025_Điều6$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều6_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Cơ quan quản lý thuế, cơ quan nhà nước, tổ chức khác của nhà nước
được giao nhiệm vụ quản lý thu ngân sách nhà nước thực hiện việc quản lý thuế,
các khoản thu khác thuộc ngân sách nhà nước theo quy định của Luật này và quy
định khác của pháp luật có liên quan.$md$,$md$Luật quản lý thuế 2025_Điều6$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều6_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Các nguyên tắc áp dụng trong quản lý thuế:
quản lý thuế để xác định bản chất của các giao dịch, hoạt động sản xuất, kinh
doanh của người nộp thuế làm cơ sở xác định nghĩa vụ thuế, khoản thu khác, đảm
bảo các giao dịch của người nộp thuế thể hiện đúng bản chất thương mại, kinh tế,
tài chính, không phụ thuộc hình thức của giao dịch được thể hiện trong hợp đồng,
văn bản giữa người nộp thuế với bên liên quan;
nguồn lực và nâng cao hiệu quả quản lý;
<!-- Page Break -->
