insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Người nộp thuế không có khả năng nộp hồ sơ khai thuế, khoản thu khác
đúng thời hạn trong trường hợp bất khả kháng quy định tại khoản 21 Điều 4 của
Luật này được gia hạn như sau:
lần phát sinh nghĩa vụ thuế, khoản thu khác, thời gian gia hạn không quá 30 ngày
kẻ từ ngày hết thời hạn nộp hồ sơ khai thuế, khoản thu khác.
Đối với trường hợp khai quyết toán thuế, khoản thu khác, thời gian gia hạn
không quá 60 ngày kể từ ngày hết thời hạn nộp hồ sơ khai quyết toán thuế, khoản
thu khác;
thu khác quy định tại điêm a khoản này, Chính phủ quy định phù hợp với tình
hình thực tế.$md$,$md$Luật quản lý thuế 2025_Điều12$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K4_Da$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm a$md$,$md$Đối với trường hợp khai thuế, khoản thu khác theo tháng, quý, năm, từng$md$,$md$Luật quản lý thuế 2025_Điều12_K4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K4_Db$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm b$md$,$md$Trường hợp phải kéo dài thời gian gia hạn nộp hồ sơ khai thuế, khoản$md$,$md$Luật quản lý thuế 2025_Điều12_K4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K5$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 5$md$,$md$Người nộp thuế phát hiện hồ sơ khai thuế, khoản thu khác đã nộp cho cơ
quan thuế có sai, sót thì được khai bổ sung hồ sơ khai thuế, khoản thu khác trong
thời hạn 05 năm kẻ từ ngày hết thời hạn nộp hồ sơ khai thuế, khoản thu khác của
kỳ tính thuế có sai, sót đối với các trường hợp sau:
thanh tra, kiểm tra;
khác nêu tại quyết định thanh tra, kiểm tra;
bổ sung hỗ sơ khai thuế, khoản thu khác để phục vụ điều tra vụ án;
đến phạm vi, thời kỳ đã thanh tra, kiểm tra dẫn đến phát sinh tăng số thuế phải
nộp, giảm số thuế đã được miễn, giảm, hoàn, giảm số thuế được khấu trừ, giảm
số thuế đã nộp thừa thì người nộp thuế được bồ sung hồ sơ giải trình với cơ quan
thuế. Cơ quan thuế có trách nhiệm rà soát hồ sơ giải trình liên quan đến phạm vi,
thời kỳ đã thanh tra, kiểm tra của người nộp thuế, trường hợp chấp thuận hồ sơ
<!-- Page Break -->
## Page 11
I1
giải trình của người nộp thuế thì cơ quan thuế ban hành thông báo chấp thuận cho
người nộp thuế điều chỉnh hồ sơ khai thuế.
Người nộp thuế bị xử lý theo quy định như đối với trường hợp cơ quan
thuế, cơ quan có thẩm quyền thanh tra, kiểm tra phát hiện. Công chức thanh tra,
kiểm tra thuế liên quan đến hồ sơ giải trình chịu trách nhiệm về sai, sót chưa được
phát hiện đầy đủ qua kiểm tra trong trường hợp tuân thủ chưa đúng quy định tại
điểm n khoản 1 Điều 38 của Luật này;
có thâm quyền liên quan đến nội dung xác định nghĩa vụ thuế của người nộp thuế,
Trường hợp người nộp thuế khai bổ sung làm tăng số thuế phải nộp, giảm số thuế
được khấu trừ, miễn, giảm, hoàn thì bị xử lý theo quy định như đối với trường
hợp cơ quan thuế, cơ quan có thẩm quyền thanh tra, kiểm tra phát hiện;
được khai bổ sung hồ sơ khai thuế, khoản thu khác để phục vụ điều tra vụ án và
trách nhiệm thông báo của cơ quan điều tra cho cơ quan thuế khi kết thúc yêu
cầu liên quan đến vụ án quy định tại điểm e khoản này và các trường hợp khai
bồ sung theo kết luận, quyết định của cơ quan nhà nước có thẩm quyền liên quan
đến nội dung xác định nghĩa vụ thuế của người nộp thuế quy định tại điểm đ
khoản này.$md$,$md$Luật quản lý thuế 2025_Điều12$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
