insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K5_De$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm e$md$,$md$Hồ sơ không thuộc trường hợp cơ quan điều tra yêu cầu không được khai$md$,$md$Luật quản lý thuế 2025_Điều12_K5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
