insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Đối với hàng hóa xuất khẩu, nhập khẩu thì hồ sơ hải quan theo quy định
của Luật Hải quan được sử dụng làm hồ sơ khai thuế. Việc khai thuế, khai bổ
sung, thời hạn nộp hồ sơ khai thuế, cơ quan hải quan tiếp nhận hồ sơ khai thuế, tỷ
giá tính thuế đối với hàng hóa xuất khẩu, hàng hóa nhập khẩu thực hiện theo quy
định của pháp luật về hải quan.$md$,$md$Luật quản lý thuế 2025_Điều12$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K7$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 7$md$,$md$Đồng tiền khai thuế, khoản thu khác là Đồng Việt Nam; đồng tiền tính
thuế, khoản thu khác là Đồng Việt Nam. Chính phủ quy định các trường hợp được
khai, tính bằng ngoại tệ.$md$,$md$Luật quản lý thuế 2025_Điều12$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K8$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 8$md$,$md$Chính phủ quy định chỉ tiết các khoản 1, 2, 3, 5, 6, 7 và điểm b khoản 4
Điều này và các nội dung sau: các trường hợp không phải nộp hồ sơ khai thuế,
khoản thu khác; kỳ tính thuế; thời hạn nộp hồ sơ khai thuế, khoản thu khác, trừ
trường hợp quy định tại khoản 9 Điều này; việc khai thuế, khoản thu khác, tính
thuế, khoản thu khác, nộp thuế, khoản thu khác đối với hoạt động dầu khí và bán
dầu khí; tỷ giá khai thuế, khoản thu khác quy đổi; việc kê khai, xác định giá tính
thuế đối với giao dịch liên kết, báo cáo lợi nhuận liên quốc gia; phân bổ nghĩa vụ
thuế, khoản thu khác phải nộp; trình tự, thủ tục tiếp nhận và xử lý hồ sơ đối với
trường hợp cơ quan quản lý thuế tính thuế, khoản thu khác, thông báo thuế, khoản
thu khác.$md$,$md$Luật quản lý thuế 2025_Điều12$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều12_K9$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 9$md$,$md$Bộ trưởng Bộ Tài chính quy định chỉ tiết điểm a khoản 4 Điều này và
