insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Đối với các loại thuế khác và khoản thu khác:
Hộ kinh doanh, cá nhân kinh doanh tự xác định số thuế, khoản thu khác phải
nộp theo quy định của pháp luật về thuế, quy định khác của pháp luật có liên quan.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Hộ kinh doanh, cá nhân kinh doanh thực hiện khai thuế, tính thuế đối với
từng loại thuế theo kỳ tính thuế. Cơ quan thuế căn cứ vào cơ sở dữ liệu quản lý
thuế cung cấp thông tin để hỗ trợ hộ kinh doanh, cá nhân kinh doanh trong việc
khai thuế và tính thuế.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Đối với hộ kinh doanh, cá nhân kinh doanh có hoạt động kinh doanh trên
nền tảng thương mại điện tử, nền tảng số khác:
nền tảng số khác có chức năng đặt hàng trực tuyến và chức năng thanh toán, chủ
quản nền tảng thương mại điện tử, nền tảng số khác (trong nước hoặc nước ngoài)
<!-- Page Break -->
