insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều14$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 14. Nộp thuế, khoản thu khác, tiền chậm nộp, tiền phạt; gia hạn$md$,$md$Nộp thuế, khoản thu khác, tiền chậm nộp, tiền phạt; gia hạn
nộp thuế, khoản thu khác, tiền chậm nộp, tiền phạt$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều14_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Thời hạn nộp thuế, khoản thu khác, tiền chậm nộp, tiền phạt:
thuế, khoản thu khác chậm nhất là ngày cuối cùng của thời hạn nộp hồ sơ khai
thuế, khoản thu khác. Đối với trường hợp khai bổ sung hồ sơ khai thuế, khoản thu
khác, thời hạn nộp thuế, khoản thu khác là thời hạn nộp hồ sơ khai thuế, khoản
thu khác của kỳ tính thuế có sai, sót. Đối với trường hợp tạm nộp theo quý, thời
hạn nộp thuế thực hiện theo quy định của Chính phủ;
báo nộp thuế, khoản thu khác, quyết định xử lý về thuế, khoản thu khác thì thời
hạn nộp thuế, khoản thu khác, tiền chậm nộp, tiền phạt là thời hạn ghỉ trên thông
<!-- Page Break -->
## Page 14
14
báo, quyết định của cơ quan quản lý thuế theo quy định của pháp luật. Trường
hợp cơ quan nhà nước có thâm quyền ban hành văn bản xử lý về thuế, khoản thu
khác thì thời hạn nộp thuế, khoản thu khác, tiền chậm nộp, tiền phạt là thời hạn
ghi trên văn bản của cơ quan nhà nước có thâm quyền.
Trong thời gian giải quyết khiếu nại, khởi kiện của người nộp thuế về số
tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt phải nộp thì người nộp thuế
vẫn phải nộp đủ số tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt phải nộp,
trừ trường hợp cơ quan nhà nước có thẩm quyền quyết định tạm đình chỉ việc thực
hiện thông báo nộp thuế, khoản thu khác, quyết định, văn bản xử lý về thuế, khoản
thu khác, tiền chậm nộp, tiền phạt của cơ quan quản lý thuế, cơ quan nhà nước có
thẩm quyền;
quy định của pháp luật về thuế, thời hạn nộp thuế thực hiện theo quy định của
Luật Thuế xuất khẩu, thuế nhập khẩu; trường hợp phát sinh số tiền thuế phải nộp
sau khi thông quan hoặc giải phóng hàng hóa thì thời hạn nộp thuế phát sinh thực
hiện theo quy định của Bộ trưởng Bộ Tài chính.$md$,$md$Luật quản lý thuế 2025_Điều14$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
