insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều20_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Các trường hợp được khoanh tiền thuế nợ:
mắt tích hoặc mắt năng lực hành vi dân sự;
