insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều25_K1_Dh$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm h$md$,$md$Người nộp thuế không chấp hành quyết định kiểm tra của cơ quan hải quan;$md$,$md$Luật quản lý thuế 2025_Điều25_K1$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều25_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Cơ quan hải quan ấn định số tiền thuế phải nộp dựa trên các căn cứ: hàng
hóa thực tế xuất khẩu, nhập khẩu; căn cứ tính thuế, phương pháp tính thuế; cơ sở
dữ liệu quản lý thuế và cơ sở dữ liệu thương mại; hồ sơ hải quan; tài liệu, sổ sách,
chứng từ, dữ liệu kế toán, kết quả thanh tra, kiểm tra, kết luận của cơ quan có
thẩm quyền hoặc bản án, quyết định của Toà án đã có hiệu lực pháp luật và các
thông tin khác có liên quan đến hàng hóa xuất khẩu, nhập khẩu.$md$,$md$Luật quản lý thuế 2025_Điều25$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều25_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Chính phủ quy định chỉ tiết khoản 1, khoản 2 Điều này và các nội dung
sau: phương pháp ấn định thuế; thâm quyền, thủ tục ấn định thuế; trách nhiệm của
người nộp thuế, người khai thuế, cơ quan hải quan trong việc ấn định thuế.
Chương II
HÓA ĐƠN ĐIỆN TỬ, CHỨNG TỪ ĐIỆN TỬ$md$,$md$Luật quản lý thuế 2025_Điều25$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 26. Hóa đơn điện tử$md$,$md$Hóa đơn điện tử$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Hóa đơn điện tử là hóa đơn ở dạng dữ liệu điện tử do tổ chức, hộ kinh
doanh, cá nhân kinh doanh bán hàng hóa, cung cấp dịch vụ lập để ghi nhận thông
tin bán hàng hóa, cung cấp dịch vụ theo quy định của pháp luật về thuế và pháp
luật về kế toán.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Hóa đơn điện tử gồm hóa đơn điện tử có mã của cơ quan thuế, hóa đơn
điện tử không có mã của cơ quan thuế, hóa đơn điện tử khởi tạo từ máy tính tiền
có kết nối dữ liệu với cơ quan thuế.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Đối tượng sử dụng hóa đơn điện tử:
đơn điện tử không có mã của cơ quan thuế, hóa đơn điện tử khởi tạo từ máy tính
tiền có kết nói dữ liệu với cơ quan thuế theo quy định của Chính phủ;
đơn điện tử theo quy định của Chính phủ và doanh nghiệp, tổ chức kinh tế, tổ
chức có nhu cầu sử dụng hóa đơn điện tử phải khai và nộp thuế trước khi được cơ
quan thuế cấp hóa đơn điện tử có mã cho từng lần phát sinh giao dịch bán hàng
hóa, cung cấp dịch vụ.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K3_Da$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm a$md$,$md$Người nộp thuế sử dụng hóa đơn điện tử có mã của cơ quan thuế, hóa$md$,$md$Luật quản lý thuế 2025_Điều26_K3$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K3_Db$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm b$md$,$md$Hộ kinh doanh, cá nhân kinh doanh không thuộc trường hợp sử dụng hóa$md$,$md$Luật quản lý thuế 2025_Điều26_K3$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Dịch vụ về hóa đơn điện tử gồm dịch vụ cung cấp giải pháp lập, truyền,
lưu trữ hóa đơn điện tử có mã hoặc không có mã, hóa đơn điện tử khởi tạo từ
máy tính tiền có kết nối dữ liệu với cơ quan thuế. Tổ chức cung cấp dịch vụ hóa
đơn điện tử phải đáp ứng điều kiện kỹ thuật, nhân sự, bảo đảm an toàn thông tin,
<!-- Page Break -->
## Page 33
33
bảo mật dữ liệu theo quy định của Bộ trưởng Bộ Tài chính và có trách nhiệm
phối hợp với cơ quan thuế trong việc trao đổi, cung cấp thông tin phục vụ công
tác quản lý thuế.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K5$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 5$md$,$md$Nguyên tắc, quyền và trách nhiệm lập, quản lý, sử dụng hóa đơn điện tử:
bán hàng hóa, cung cấp dịch vụ để giao cho người mua theo định dạng chuẩn dữ
liệu và phải ghi đầy đủ nội dung theo quy định của pháp luật về thuế và pháp luật
về kế toán, bảo đảm phản ánh đầy đủ, trung thực nội dung nghiệp vụ kinh tế phát
sinh và chịu trách nhiệm trước pháp luật về tính chính xác của hóa đơn đã lập, trừ
trường hợp không phải sử dụng hóa đơn điện tử theo quy định của Chính phủ;
của pháp luật về giao dịch điện tử, pháp luật về kế toán và pháp luật về thuế;
ứng yêu cầu kết nối, lưu trữ, bảo mật và truy xuất hóa đơn điện tử theo đúng định
dạng chuẩn và quy định của pháp luật;
cơ sở đữ liệu về hóa đơn; được kết nối, chia sẻ với các cơ quan, tổ chức có liên
quan nhằm phục vụ công tác quản lý nhà nước và bảo vệ quyên lợi người mua.
Cơ quan thuế có trách nhiệm tổ chức, xây dựng, quản lý và vận hành hệ
thống dữ liệu hóa đơn điện tử. Căn cứ kết quả phân tích rủi ro, cơ quan thuế áp
dụng các biện pháp quản lý phù hợp, bao gồm cả việc ngừng, tạm ngừng sử dụng
hóa đơn điện tử đối với các trường hợp có rủi ro cao về thuế và hóa đơn;
chế kiểm tra, phát hiện, cảnh báo trong sử dụng hóa đơn điện tử và cung cấp thông
tin cho cơ quan thuế;
đơn điện tử khi mua hàng hóa, dịch vụ; được hưởng các biện pháp khuyến khích
theo quy định của pháp luật.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
