insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K5_Dđ$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm đ$md$,$md$Người nộp thuế có trách nhiệm triển khai hệ thống hạ tầng kỹ thuật đáp$md$,$md$Luật quản lý thuế 2025_Điều26_K5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
