insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Chính phủ quy định các nội dung sau: loại hóa đơn điện tử; đối tượng sử
dụng; nội dung, thời điểm lập hóa đơn điện tử; trường hợp không phải sử dụng
hóa đơn điện tử; trường hợp sử dụng hóa đơn điện tử được miễn phí dịch vụ;
nhiệm vụ, quyền hạn, trách nhiệm của tổ chức, cá nhân trong việc quản lý, sử
dụng hóa đơn điện tử.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều26_K7$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 7$md$,$md$Bộ trưởng Bộ Tài chính quy định các nội dung sau: đăng ký sử dụng hóa
đơn điện tử; định dạng hóa đơn điện tử; ủy nhiệm lập hóa đơn điện tử; xử lý hóa
<!-- Page Break -->
## Page 34
34
đơn điện tử đã lập; ký hiệu mẫu, ký hiệu và mẫu hóa đơn điện tử tham khảo;
chuyên đổi áp dụng hóa đơn điện tử; tiêu chí xác định người nộp thuế có rủi ro
cao trong đăng ký sử dụng hóa đơn điện tử; các trường hợp ngừng, tạm ngừng sử
dụng hóa đơn điện tử; biện pháp khuyến khích người mua lấy hóa đơn khi mua
hàng hóa, dịch vụ và thực hiện khen thưởng người tiêu dùng tố giác người bán
không lập và giao hóa đơn điện tử từ nguồn kinh phí do ngân sách nhà nước bảo
đảm trong dự toán chỉ thường xuyên hằng năm theo quy định của pháp luật.$md$,$md$Luật quản lý thuế 2025_Điều26$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều27$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 27. Chứng từ điện tử$md$,$md$Chứng từ điện tử$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều27_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Chứng từ điện tử là chứng từ thu thuế, phí, lệ phí hoặc chứng từ khấu trừ
thuế ở dạng dữ liệu điện tử do cơ quan quản lý thuế hoặc tổ chức có trách nhiệm
khấu trừ thuế cấp cho người nộp thuế bằng phương tiện điện tử.$md$,$md$Luật quản lý thuế 2025_Điều27$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
