insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều42$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 42. Trách nhiệm và quyền hạn của cơ quan quản lý thuế trong$md$,$md$Trách nhiệm và quyền hạn của cơ quan quản lý thuế trong
việc giải quyết khiếu nại về thuế
1;Cỡ quan quản lý thuế nhận được khiếu nại về việc thực hiện pháp luật về
thuế có quyền yêu cầu người khiếu nại cung cấp hồ sơ, tài liệu liên quan đến việc
khiếu nại; nếu người khiếu nại từ chối cung cấp hồ sơ, tài liệu thì có quyền từ chối
xem xét giải quyết khiếu nại.$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều42_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Cơ quan quản lý thuế phải hoàn trả số tiền thuế, khoản thu khác, tiền
chậm nộp, tiền phạt thu không đúng cho người nộp thuế, bên thứ ba trong thời
hạn 15 ngày kể từ ngày nhận được quyết định xử lý của cơ quan có thầm quyền.$md$,$md$Luật quản lý thuế 2025_Điều42$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều42_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Đối với vụ việc khiếu nại phức tạp, thủ trưởng cơ quan quản lý thuế là
người giải quyết khiếu nại thực hiện tham vấn các cơ quan, tổ chức có liên quan,
bao gồm cả khiếu nại lần đầu. Khi thực hiện việc tham vấn, thủ trưởng cơ quan
quản lý thuế phải ban hành quyết định thành lập Hội đồng tham vấn. Hội đồng
tham vấn hoạt động theo nguyên tắc tập thẻ, biểu quyết theo đa số. Kết quả biểu
quyết là cơ sở để thủ trưởng cơ quan quản lý thuế tham khảo khi ra quyết định xử
lý khiếu nại. Thủ trưởng cơ quan quản lý thuế là người ra quyết định và chịu trách
nhiệm về quyết định xử lý khiếu nại.$md$,$md$Luật quản lý thuế 2025_Điều42$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều43$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 43. Khởi kiện$md$,$md$Khởi kiện
