insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều15_K1$md$,$md$68-ndcp.signed$md$,$md$Khoản 1$md$,$md$Trách nhiệm của Ủy ban nhân dân cấp tỉnh
đủ các quy định của pháp luật về đăng ký kinh doanh, quản lý hộ kinh doanh,
cá nhân kinh doanh và cung câp thông tin cho cơ quan thuê theo quy định;
vị liên quan thiết lập, cập nhật và chia sẻ cơ sở đữ liệu hộ kinh doanh, cá nhân
kinh doanh với cơ quan thuế; bảo đảm kết nối đồng bộ, chính xác giữa dữ liệu
đăng ký kinh doanh và cơ sở dữ liệu thuế;
,©) Chỉ đạo cơ quan quản lý thị trường, công an, tài chính, thông tin và
truyền thông, nội vụ và các cơ quan chuyên môn trực thuộc phối hợp với cơ
quan thuế trong kiểm tra, giám sát hoạt động kinh doanh; phòng, chống thất thu
thuế; xử lý các hành vi vi phạm pháp luật về thuế và hoạt động kinh doanh;
tử, chứng từ điện tử đối với hộ kinh doanh, cá nhân kinh doanh trên địa bàn;
chỉ đạo cơ quan chuyên môn hỗ trợ, hướng dẫn người nộp thuế sử dụng hóa
đơn điện tử;
hoạt động của hộ kinh doanh, cá nhân kinh doanh trên địa bàn; bảo đảm việc
cung câp thông tin đây đủ, kịp thời, đúng thực tế cho cơ quan thuế.$md$,$md$68-ndcp.signed_Điều15$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều15_K1_Da$md$,$md$68-ndcp.signed$md$,$md$Điểm a$md$,$md$Chỉ đạo các sở, ban, ngành và Ủy ban nhân dân cấp xã thực hiện đầy$md$,$md$68-ndcp.signed_Điều15_K1$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều15_K1_Db$md$,$md$68-ndcp.signed$md$,$md$Điểm b$md$,$md$Chỉ đạo Sở Tài chính, các cơ quan cấp phép chuyên ngành và các đơn$md$,$md$68-ndcp.signed_Điều15_K1$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều15_K1_Dđ$md$,$md$68-ndcp.signed$md$,$md$Điểm đ$md$,$md$Bảo đảm nguồn lực, cơ sở hạ tầng kỹ thuật để triển khai hóa đơn điện$md$,$md$68-ndcp.signed_Điều15_K1$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều15_K2$md$,$md$68-ndcp.signed$md$,$md$Khoản 2$md$,$md$Trách nhiệm của Ủy ban nhân dân cấp xã
kinh doanh, cá nhân kinh doanh đang hoạt động trên địa bàn; phát hiện và thông
báo kịp thời cho cơ quan thuế các trường hợp: bắt đầu kinh doanh, tạm ngừng,
chấm đứt hoạt động, thay đổi ngành nghề, địa điểm kinh doanh trên địa bàn,
kinh doanh không đăng ký, kinh doanh trái phép, ngoài địa điểm được cấp phép;
chính sách pháp. luật về thuế đến người dân, hộ kinh doanh và cá nhân kinh
doanh. Hỗ trợ công tác tuyên truyền lưu động, niêm yết thông tin, hướng dẫn
người nộp thuế thực hiện kê khai, nộp thuế đúng quy định. Phản ánh các khó
khăn, vướng mắc của người dân liên quan đến chính sách thuế đến cơ quan thuế
để cùng phối hợp giải quyết;
<!-- Page Break -->
# Page 16
16
phối hợp và hỗ trợ cơ quan thuế theo thẩm quyền trong việc phát hiện, xác minh
và xử lý các hành vi vi phạm pháp luật thuế của hộ kinh doanh, cá nhân kinh
doanh khi có yêu cầu của cơ quan thuế; bao gồm việc xác minh thông tin người
nộp thuế, địa chỉ kinh doanh, quy mô hoạt động kinh doanh, số lượng hộ kinh
doanh, cá nhân kinh doanh, doanh thu, phối hợp lập biên bản vi phạm và cung
cấp ' hỗ sơ, tài liệu liên quan trên địa bàn theo quy định của pháp luật quản lý
thuế và pháp luật có liên quan;
liên quan trong việc kiểm tra, phát hiện, ngăn chặn và xử lý hành vi không đăng
ký kinh doanh, kinh doanh không khai thuế, trốn thuế;
doanh hoạt động kinh doanh tại các địa điểm kinh doanh trái phép, hoạt động
tại địa điểm kinh doanh không đủ điều kiện theo quy định của pháp luật;
quy định về tình hình hộ kinh doanh, cá nhân kinh doanh trên địa bàn; đề xuất
biện pháp tăng cường quản lý, xử lý vướng mắc phát sinh;
