insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K8$md$,$md$TT111-2013$md$,$md$Khoản 8$md$,$md$Thu nhập từ nhượng quyền thương mại
Nhượng quyền thương mại là hoạt động thương mại, theo đó bên nhượng
quyền cho phép và yêu cầu bên nhận quyên tự mình tiến hành việc mua bán
hàng hóa, cung ứng dịch vụ theo các điều kiện của bên nhượng quyền tại hợp
đồng nhượng quyền thương mại.
Thu nhập từ nhượng quyền thương mại là các khoản thu nhập mà cá nhân
nhận được từ các hợp đồng nhượng quyền thương mại nêu trên, bao gồm cả
trường hợp nhượng lại quyên thương mại theo quy định của pháp luật về
nhượng quyên thương mại.$md$,$md$TT111-2013_Điều2$md$,null,$md$2013-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TT111-2013_Điều2_K9$md$,$md$TT111-2013$md$,$md$Khoản 9$md$,$md$Thu nhập từ nhận thừa kế
